@노드(id=_법ID + "-6-4", 법령=_법, 조="6", 항="4", 제목="창업 후 3개 과세연도 내 2027년까지 에너지신기술중소기업 해당 — 해당일 후 최초 소득 과세연도부터 5개 과세연도 50%(①② 적용분 제외, 비해당 시 중단)", mst=_법MST,
    원문="④ 창업일이 속하는 과세연도와 그 다음 3개 과세연도가 지나지 아니한 중소기업으로서 2027년 12월 31일까지 … 에너지신기술중소기업 … 에 해당하는 경우에는 … 100분의 50에 상당하는 세액을 감면한다.",
    종료일="20271231", 준용=(_영ID + "-5-11", _영ID + "-5-15"), 산출=("조특_6_기본감면",), 우선순위=5,
    비고="감면유형 '에너지신기술중소기업'. 해당사업_산출세액은 영 §5⑮ 감면소득에 대한 세액으로 호출자가 넘김. 사실 에너지신기술비해당일.")
def 법6_4(ctx):
    if not _유형(ctx, "에너지신기술중소기업"):
        return 미적용("감면유형에 에너지신기술중소기업 없음")
    해당 = _d(ctx.사실값("에너지신기술해당일"))
    창업 = _d(ctx.사실값("창업일"))
    if 해당 is None or 창업 is None:
        return 미적용("에너지신기술 해당일·창업일 미제출")
    if 해당 > date(2027, 12, 31):
        return 미적용("2027년 12월 31일 후 해당 — 일몰")
    if 해당.year > 창업.year + 3:
        return 미적용("창업 과세연도와 그 다음 3개 과세연도 경과")
    g = _공통게이트(ctx)
    if g:
        return 미적용(g)
    if not ctx.값("조특_6_에너지대상", False):
        return 미적용("고효율제품등 제조 중소기업 아님(영 §5⑪)")
    연 = _연도(ctx)
    비해당 = _d(ctx.사실값("에너지신기술비해당일"))
    if 비해당 and 연 >= 비해당.year:
        return 미적용("에너지신기술중소기업에 해당하지 않게 된 과세연도부터 미적용")
    기간 = _감면기간(해당, ctx.사실값("최초소득과세연도"))
    if not (기간[0] <= 연 <= 기간[1]):
        return 미적용("감면기간(%d~%d) 밖" % 기간)
    세 = _세액(ctx)
    return {"조특_6_기본감면": {"항": "4", "율": 0.5, "세액": None if 세 is None else int(세 * 0.5), "감면소득": ctx.값("조특_6_에너지감면소득", None)}}


