@노드(id=_법ID + "-6-7", 법령=_법, 조="6", 항="7", 제목="고용증가 추가감면 — 세액 × (당해 상시근로자 − 직전)/직전, 한도 50%(75% 감면 연도 25%), 1% 미만 버림, 100% 감면 연도 미적용", mst=_법MST,
    원문="⑦ … 해당 과세연도의 상시근로자 수가 직전 과세연도의 상시근로자 수(직전 과세연도의 상시근로자 수가 업종별최소고용인원에 미달하는 경우에는 업종별최소고용인원을 말한다)보다 큰 경우에는 …",
    준용=(_영ID + "-5-14", _영ID + "-5-18"), 산출=("조특_6_고용추가감면",),
    비고="직전 상시근로자 수가 업종별최소고용인원에 미달하면 비교·산식 분모 모두 최소고용인원으로 본다(해석). 사실 상시근로자(해당 과세연도).")
def 법6_7(ctx):
    기본 = ctx.값("조특_6_기본감면", None)
    if not 기본:
        return 미적용("①②④⑤⑥ 감면 미적용 연도")
    if 기본["율"] >= 1.0 and 기본["항"] in ("1", "6"):
        return 미적용("100분의 100 감면 과세연도 — 추가감면 없음")
    당해 = ctx.사실값("상시근로자")
    if 당해 is None:
        return 미적용("해당 과세연도 상시근로자 수 미제출")
    최소 = ctx.값("조특_6_최소고용인원")
    if float(당해) < 최소:
        return 미적용("업종별최소고용인원 미만 고용")
    직전 = max(ctx.값("조특_6_직전상시근로자"), 최소)
    if float(당해) <= 직전:
        return 미적용("상시근로자 증가 없음")
    율 = math.floor((float(당해) - 직전) / 직전 * 100 + 1e-9) / 100
    한도 = 0.25 if 기본["율"] == 0.75 and 기본["항"] in ("1", "5", "6") else 0.5
    율 = min(율, 한도)
    세 = _세액(ctx)
    return {"조특_6_고용추가감면": {"율": 율, "세액": None if 세 is None else int(세 * 율)}}


