@노드(id=_법ID + "-7-1", 법령=_법, 조="7", 항="1", 제목="중소기업 특별세액감면 — 2028년 이전 종료 과세연도, 감면업종 사업장 소득 세액 × 감면비율(소기업 10/20/30%, 중기업 5/10/15%), 한도 1억(상시근로자 감소 1명당 5백만 차감)", mst=_법MST,
    원문="① 중소기업 중 … 감면 업종을 경영하는 기업에 대해서는 2028년 12월 31일 이전에 끝나는 과세연도까지 해당 사업장에서 발생한 소득에 대한 소득세 또는 법인세에 제2호의 감면 비율을 곱하여 계산한 세액상당액(제3호 … 한도)을 감면한다.",
    종료일="20281231", 준용=(_영ID + "-6-4",), 산출=("조특_7_감면율",), 우선순위=10,
    비고="감면유형 '중소기업특별감면'. 사실 업종(_업종_7_1 코드), 사업장지역('수도권'·'수도권외'), 본점수도권(법인), 일반서적출판업. 의료업 의원·치과의원·한의원은 요양급여비율≥80%·종합소득금액≤1억 필요(사실 의원급). 통관대리업은 나·다·바목 × 50%.")
def 법7_1(ctx):
    if not _유형(ctx, "중소기업특별감면"):
        return 미적용("감면유형에 중소기업특별감면 없음")
    if _연도(ctx) > 2028:
        return 미적용("2028년 12월 31일 후 끝나는 과세연도 — 일몰")
    if _중소(ctx) is False:
        return 미적용("중소기업 아님")
    업종 = ctx.사실값("업종")
    if 업종 not in _업종_7_1:
        return 미적용("①1호 감면 업종 아님")
    if 업종 == "의료업" and ctx.사실값("의원급", False):
        if _f(ctx.사실값("요양급여비율")) < 0.8 or _f(ctx.사실값("종합소득금액")) > 100_000_000:
            return 미적용("의원·치과의원·한의원 — 요양급여비율 80% 미만 또는 종합소득금액 1억 초과")
    수도권 = ctx.사실값("사업장지역", "수도권외") == "수도권" or bool(ctx.사실값("본점수도권", False))
    소 = ctx.값("조특_7_소기업", False)
    도매 = 업종 in _도매업등
    if 소:
        목, 율 = ("가", 0.10) if 도매 else (("나", 0.20) if 수도권 else ("다", 0.30))
    else:
        if 도매:
            if 수도권:
                return 미적용("중기업이 수도권에서 도매업등 — 감면 비율 없음")
            목, 율 = "라", 0.05
        elif 수도권:
            if not ctx.사실값("일반서적출판업", False):
                return 미적용("중기업이 수도권에서 일반 서적 출판업 외 업종 — 감면 비율 없음")
            목, 율 = "마", 0.10
        else:
            목, 율 = "바", 0.15
    if 업종 == "통관대리관련서비스업" and 목 in ("나", "다", "바"):
        율 = round(율 * 0.5, 6)
    return {"조특_7_감면율": {"목": 목, "율": 율, "항": "1"}}


@노드(id=_법ID + "-7-2", 법령=_법, 조="7", 항="2", 제목="10년 이상 계속 경영·종합소득금액 1억 이하·성실사업자 요건 중소기업 — ① 감면비율 × 110%", mst=_법MST,
    원문="② … 1. 해당 과세연도 개시일 현재 10년 이상 계속하여 해당 업종을 경영한 기업일 것 2. 해당 과세연도의 종합소득금액이 1억원 이하일 것 3. 「소득세법」 제59조의4제9항에 따른 성실사업자로서 …",
    산출=("조특_7_감면율",), 우선순위=5, 비고="3호의 같은 법 제122조의3제1항제2호·제4호 요건 충족은 호출자 판정(사실 성실사업자요건).")
def 법7_2(ctx):
    if _f(ctx.사실값("계속경영_년")) < 10 or ctx.사실값("종합소득금액") is None or _f(ctx.사실값("종합소득금액")) > 100_000_000 or not ctx.사실값("성실사업자요건", False):
        return 미적용("②1~3호 요건 미충족")
    기본 = 법7_1(ctx)
    if isinstance(기본, 미적용):
        return 기본
    r = dict(기본["조특_7_감면율"])
    r["율"] = round(r["율"] * 1.1, 6)
    r["항"] = "2"
    return {"조특_7_감면율": r}


