    ok = (not ctx.사실값("공공기관등", False) and ctx.사실값("주된사업") not in ("소비성서비스업", "부동산임대업", "중견법배제업종")
          and ctx.사실값("중견독립성", True) and sum(float(x) for x in 매출) / len(매출) < 300_000_000_000 and not ctx.사실값("법인령42조2항_해당", False))
