@노드(id=_법ID + "-7의4-2", 법령=_법, 조="7의4", 항="2", 제목="상생결제 공제액 = (15일 이내 A − B) × 0.5% + (15~30일 C − D) × 0.3% + (30~60일 E − F) × 0.15%, B = 현금성결제금액 감소분, D·F = 이월 초과분(각 항 음수 0)", mst=_법MST,
    원문="(A - B) × 1천분의 5 … B: 직전 과세연도에 지급한 … 현금성결제금액 … 이 해당 과세연도의 현금성결제금액을 초과하는 경우 그 초과하는 금액 … (C - D) × 1천분의 3 … (E - F) × 1만분의 15",
    준용=(_영ID + "-6의4-2",), 산출=("조특_7의4_공제계산액",), 비고="사실 상생결제_15일이내, 상생결제_15_30일, 상생결제_30_60일, 현금성결제금액, 직전_현금성결제금액.")
def 법7의4_2(ctx):
    A = _f(ctx.사실값("상생결제_15일이내"))
    C = _f(ctx.사실값("상생결제_15_30일"))
    E = _f(ctx.사실값("상생결제_30_60일"))
    B = max(0.0, _f(ctx.사실값("직전_현금성결제금액")) - _f(ctx.사실값("현금성결제금액")))
    D = max(0.0, B - A)
    F = max(0.0, D - C)
    x = max(0.0, (A - B) * 0.005) + max(0.0, (C - D) * 0.003) + max(0.0, (E - F) * 0.0015)
    return {"조특_7의4_공제계산액": _내림(x)}


