def _졸업연도(사유연도, 사유유형, 상장, 구분):
    """최초로 중소기업에 해당하지 아니하게 된 과세연도(유예기간이 지난 첫 과세연도)."""
    y = int(사유연도)
    if 사유유형 == "별표개정":
        return y + 4
    if 구분 == "20" and y <= 2023:
        return y + 4
    return y + (8 if 상장 else 6)


