def _10_발생기한(ctx, 반도체=False):
    연 = _연도(ctx)
    한 = 2031 if 반도체 else 2029
    if 연 > 한:
        return "%d년 12월 31일 후 발생 — 일몰" % 한
    if ctx.사실값("구분경리", True) is False:
        return "신성장·국가전략·일반 연구비 구분경리 안 함(④·영 §9⑫)"
    return None


def _수입비율(ctx, 비용):
    수입 = ctx.사실값("수입금액")
    if not 수입:
        return 0.0
    return float(비용) / float(수입)


