@노드(id=_법ID + "-10-1-3", 법령=_법, 조="10", 항="1", 호="3", 제목="일반연구·인력개발비 — 증가분 × 25%(중견 40%, 중소 50%)와 당기분 × (중소 25%·졸업 3년 20%·다음 2년 15%·중견 8%·그 밖 min(2%, 비율 × 1/2)) 중 선택(4년 미발생·직전<연평균이면 당기분)", mst=_법MST,
    원문="가. … 직전 과세연도에 발생한 일반연구ㆍ인력개발비를 초과하는 경우 그 초과하는 금액의 100분의 25[… 중견기업 … 100분의 40, 중소기업의 경우에는 100분의 50] … 나. … 1) 중소기업인 경우: 100분의 25 … 4) … 비율(100분의 2를 한도로 한다)",
    준용=(_영ID + "-9-1", _영ID + "-9-4", _영ID + "-9-8", _법ID + "-10-2"), 산출=("조특_10_일반공제액",),
    비고="일몰 없음. 납세의무자 선택은 큰 금액으로 본다(사실 일반공제방식='증가분'·'당기분'으로 지정 가능). 사실 직전_일반연구비.")
def 법10_1_3(ctx):
    비 = ctx.값("조특_10_일반연구비", None)
    if not 비:
        return 미적용("일반연구·인력개발비 없음")
    연 = _연도(ctx)
    중소 = _중소(ctx)
    졸 = ctx.값("조특_10_졸업연도_일반", None)
    중견 = ctx.값("조특_10_중견기업", False)
    if 중소:
        율 = 0.25
    elif 졸 is not None and 졸 <= 연 <= 졸 + 2:
        율 = 0.20
    elif 졸 is not None and 졸 + 3 <= 연 <= 졸 + 4:
        율 = 0.15
    elif 중견:
        율 = 0.08
    else:
        율 = min(0.02, _수입비율(ctx, 비) * 0.5)
    당기분 = _내림(비 * 율)
    증가분 = None
    if ctx.값("조특_10_증가분방식허용", False):
        직전 = _f(ctx.사실값("직전_일반연구비"))
        if 비 > 직전:
            증율 = 0.50 if 중소 else (0.40 if 중견 else 0.25)
            증가분 = _내림((비 - 직전) * 증율)
    방식 = ctx.사실값("일반공제방식")
    if 방식 == "증가분" and 증가분 is not None:
        return {"조특_10_일반공제액": 증가분}
    if 방식 == "당기분" or 증가분 is None:
        return {"조특_10_일반공제액": 당기분}
    return {"조특_10_일반공제액": max(당기분, 증가분)}


