@노드(id=_법ID + "-10의2-1", 법령=_법, 조="10의2", 항="1", 제목="2026년까지 국가·지자체·공공기관·지방공기업에서 받은 연구개발출연금등 — 법인세법 제113조 준용 구분경리 시 익금불산입", mst=_법MST,
    원문="① 내국인이 2026년 12월 31일까지 연구개발 등을 목적으로 국가, 지방자치단체, … 공공기관 또는 … 지방공기업으로부터 출연금 등의 자산 … 을 받은 경우로서 … 구분경리하는 경우에는 … 익금에 산입하지 아니할 수 있다.",
    종료일="20261231", 준용=(_영ID + "-9의2-2",), 산출=("조특_10의2_익금불산입액",), 비고="감면유형 '연구개발출연금'. 사실 출연금수령일, 연구개발출연금, 출연기관('국가'·'지방자치단체'·'공공기관'·'지방공기업').")
def 법10의2_1(ctx):
    if not _유형(ctx, "연구개발출연금"):
        return 미적용("감면유형에 연구개발출연금 없음")
    일 = _d(ctx.사실값("출연금수령일"))
    if 일 is None or 일 > date(2026, 12, 31):
        return 미적용("2026년 12월 31일 후 수령 또는 수령일 미제출 — 일몰")
    if ctx.사실값("출연기관") not in ("국가", "지방자치단체", "공공기관", "지방공기업"):
        return 미적용("출연기관이 국가·지자체·공공기관·지방공기업 아님")
    if not ctx.값("조특_10의2_구분경리"):
        return 미적용("법인세법 제113조 준용 구분경리 안 함(영 §9의2②)")
    return {"조특_10의2_익금불산입액": _i(ctx.사실값("연구개발출연금"))}


