@노드(id=_영ID + "-9의2-3", 법령=_영, 조="9의2", 항="3", 제목="출연금으로 취득한 자산의 익금산입 — 감가상각자산은 손금 감가상각비 상당액(처분 시 잔액 전액), 그 밖 자산은 처분 과세연도에 전액", mst=_영MST,
    원문="1. … 감가상각자산 : … 손금에 산입하는 감가상각비에 상당하는 금액을 익금에 산입하는 방법. 다만, 해당 자산을 처분하는 경우에는 … 남은 잔액을 그 처분한 날이 속하는 과세연도에 전액 익금에 산입한다. 2. 제1호 외의 자산 : … 처분한 날이 속하는 과세연도 … 전액",
    산출=("조특_10의2_자산익금산입액",), 비고="사실 자산구분('감가상각자산'·'기타'), 자산취득_출연금(익금불산입액), 감가상각비, 기익금산입액, 처분(bool).")
def 영9의2_3(ctx):
    구분 = ctx.사실값("자산구분")
    if 구분 is None:
        return 미적용("출연금 취득 자산 없음")
    총 = _i(ctx.사실값("자산취득_출연금"))
    잔 = max(0, 총 - _i(ctx.사실값("기익금산입액")))
    if ctx.사실값("처분", False):
        return {"조특_10의2_자산익금산입액": 잔}
    if 구분 == "감가상각자산":
        return {"조특_10의2_자산익금산입액": min(잔, _i(ctx.사실값("감가상각비")))}
    return {"조특_10의2_자산익금산입액": 0}


