@노드(id=_영ID + "-11-3", 법령=_영, 조="11", 항="3", 제목="특허권등 = 국내 자체 연구개발 최초 설정등록 특허·실용신안, 과학기술 기술비법(부령 요건), 기술이전법 기술(부령 요건), ④ 취득 대상 같음, ⑤ 대여 대상은 특허·실용신안·기술비법", mst=_영MST,
    원문="1. 「특허법」 및 「실용신안법」에 따라 해당 기업이 국내에서 자체 연구ㆍ개발하여 최초로 설정등록받은 특허권 및 실용신안권 2. … 기술비법 … 3. … 「기술의 이전 및 사업화 촉진에 관한 법률」 제2조제1호에 따른 기술 …",
    산출=("조특_12_특허권등",), 비고="사실 특허권등유형('특허권'·'실용신안권'·'기술비법'·'기술'), 자체개발, 부령요건충족(2·3호).")
def 영11_3(ctx):
    유형 = ctx.사실값("특허권등유형")
    자체 = bool(ctx.사실값("자체개발", False))
    if 유형 in ("특허권", "실용신안권"):
        ok = 자체
    elif 유형 in ("기술비법", "기술"):
        ok = 자체 and bool(ctx.사실값("부령요건충족", False))
    else:
        ok = False
    return {"조특_12_특허권등": {"이전취득대상": ok, "대여대상": ok and 유형 != "기술"}}


