# ============================================================== §13의3 소재·부품·장비 공동투자·외국법인 인수 (영 §12의3)
@노드(id=_영ID + "-12의3-1", 법령=_영, 조="12의3", 항="1", 제목="투자대상기업 = 소부장 특별조치법 제16조 특화선도기업등인 중소·중견기업, ② 공동투자 = 협약에 따른 공동 취득 + 각 법인 유상증자 금액 25% 이상 납입, ④ 특수관계인 = 법인세법 제2조제12호", mst=_영MST,
    원문="2. 공동투자에 참여한 각 내국법인이 투자대상기업의 유상증자 금액의 100분의 25 이상을 증자대금으로 납입할 것",
    산출=("조특_13의3_공동투자요건",), 비고="사실 특화선도기업등, 대상_중소중견, 공동투자협약, 납입비율(각 법인 최소).")
def 영12의3_1(ctx):
    ok = (bool(ctx.사실값("특화선도기업등", False)) and bool(ctx.사실값("대상_중소중견", True)) and bool(ctx.사실값("공동투자협약", False))
          and _f(ctx.사실값("납입비율")) >= 0.25)
    return {"조특_13의3_공동투자요건": ok}


@노드(id=_법ID + "-13의3-1", 법령=_법, 조="13의3", 항="1", 제목="둘 이상 내국법인이 2025년까지 소부장 중소·중견기업 유상증자에 공동투자(제품 생산 목적·특수관계 아님) — 취득가액 5% 각 법인 법인세 공제", mst=_법MST,
    원문="① 둘 이상의 내국법인 … 이 2025년 12월 31일까지 … 공동으로 취득 … 하는 경우 주식등의 취득가액의 100분의 5에 상당하는 금액을 각 내국법인의 해당 사업연도의 법인세에서 공제한다.",
    종료일="20251231", 준용=(_영ID + "-12의3-1",), 산출=("조특_13의3_공동투자공제액",), 비고="감면유형 '소부장공동투자'. 사실 취득일, 취득가액, 투자기업수, 생산목적, 취득방법('유상증자'), 특수관계(공동투자로 생긴 경우 제외).")
def 법13의3_1(ctx):
    if not _유형(ctx, "소부장공동투자"):
        return 미적용("감면유형에 소부장공동투자 없음")
    일 = _d(ctx.사실값("취득일"))
    if 일 is None or 일 > date(2025, 12, 31):
        return 미적용("2025년 12월 31일 후 취득 — 일몰")
    if _i(ctx.사실값("투자기업수"), 2) < 2:
        return 미적용("둘 이상 내국법인 공동투자 아님")
    if not ctx.사실값("생산목적", True) or ctx.사실값("취득방법", "유상증자") != "유상증자" or ctx.사실값("특수관계", False):
        return 미적용("①1~3호 요건 미충족")
    if not ctx.값("조특_13의3_공동투자요건"):
        return 미적용("영 §12의3①② 투자대상·공동투자 요건 미충족")
    return {"조특_13의3_공동투자공제액": _내림(_i(ctx.사실값("취득가액")) * 0.05)}


@노드(id=_영ID + "-12의3-5", 법령=_영, 조="12의3", 항="5", 제목="공동투자 주식 처분 추징액 — 취득 2년 내 처분은 공제세액 전액, 2년 경과 후 2년 내 처분은 공제세액 × 처분 주식수/취득 주식수(선입선출)", mst=_영MST,
    원문="1. … 2년 이내에 주식등을 처분하는 경우: … 공제받은 세액 전액 2. … 2년이 경과한 날부터 2년 이내에 주식등을 처분하는 경우: … 공제받은 세액 × … 처분한 주식등의 수 / … 취득한 주식등의 수",
    산출=("조특_13의3_처분추징액",))
def 영12의3_5(ctx):
    취득, 처분 = _d(ctx.사실값("취득일")), _d(ctx.사실값("처분일"))
    if 취득 is None or 처분 is None:
        return 미적용("처분 없음")
    세 = _i(ctx.사실값("공제받은세액"))
    if 처분 <= _add_years(취득, 2):
        return {"조특_13의3_처분추징액": 세}
    if 처분 <= _add_years(취득, 4):
        return {"조특_13의3_처분추징액": _내림(세 * _f(ctx.사실값("처분주식수")) / _f(ctx.사실값("취득주식수"), 1))}
    return {"조특_13의3_처분추징액": 0}


@노드(id=_법ID + "-13의3-2", 법령=_법, 조="13의3", 항="2", 제목="공동투자 사후관리 — 5년 내 지배주주등·3년 되는 사업연도 말까지 증자대금 80% 미만 연구·인력개발등 지출·4년 내 처분 시 공제세액(처분은 영 §12의3⑤) + 이자상당가산액", mst=_법MST,
    원문="1. … 주식등을 취득한 후 5년 이내에 투자대상기업의 지배주주등에 해당하는 경우 2. … 유상증자일부터 3년이 되는 날이 속하는 사업연도 종료일까지 … 증자대금의 100분의 80에 상당하는 금액 이상을 … 지출하지 아니하는 경우 3. … 4년 이내에 해당 주식등을 처분하는 경우",
    준용=(_영ID + "-12의3-5", _영ID + "-12의3-6"), 산출=("조특_13의3_공동투자추징",),
    비고="사실 사후사유('지배주주'·'지출미달'·'처분'), 사유일, 취득일, 소부장지출액, 증자대금, 공제사업연도. 지출미달은 3년 되는 날이 속하는 사업연도 말에 판정.")
def 법13의3_2(ctx):
    사유 = ctx.사실값("사후사유")
    취득 = _d(ctx.사실값("취득일"))
    세 = _i(ctx.사실값("공제받은세액"))
    일 = _d(ctx.사실값("사유일"))
    if 사유 == "지배주주" and 취득 and 일 and 일 <= _add_years(취득, 5):
        추 = 세
    elif 사유 == "지출미달" and _f(ctx.사실값("소부장지출액")) < _f(ctx.사실값("증자대금")) * 0.8:
        추 = 세
    elif 사유 == "처분" and 취득 and 일 and 일 <= _add_years(취득, 4):
        추 = ctx.값("조특_13의3_처분추징액")
    else:
        return {"조특_13의3_공동투자추징": {"해당": False}}
    y = ctx.사실값("공제사업연도")
    이자 = _이자22(추, date(int(y), 12, 31), 일) if (y and 일) else None
    return {"조특_13의3_공동투자추징": {"해당": True, "세액": 추, "이자상당가산액": 이자}}


@노드(id=_영ID + "-12의3-6", 법령=_영, 조="12의3", 항="6", 제목="소부장 추징 이자상당액 = 납부 세액 × (공제 사업연도 종료일 다음날 ~ 사유 사업연도 종료일) × 1일 10만분의 22, ⑫ 인수 사후관리 기간 = 인수일 사업연도 다음 사업연도 개시일부터 4년", mst=_영MST,
    원문="1. 공제받은 사업연도 종료일의 다음 날부터 납부사유가 발생한 날이 속하는 사업연도의 종료일까지의 기간 2. 제11조의2제10항제2호에 따른 율",
    산출=("조특_13의3_사후기간",))
def 영12의3_6(ctx):
    y = ctx.사실값("인수사업연도")
    if y is None:
        return 미적용("인수 사업연도 미제출")
    return {"조특_13의3_사후기간": (date(int(y) + 1, 1, 1), date(int(y) + 4, 12, 31))}


@노드(id=_영ID + "-12의3-7", 법령=_영, 조="12의3", 항="7", 제목="인수대상외국법인 = 부령 소부장 품목 생산(주식 취득은 직전 3년 평균 매출 50% 이상)·국가전략기술 사업 매출 50% 이상·합계 50% 이상, ⑨ 인수목적법인 100% 출자, ⑩ 3년 내 양수 합산, ⑪ 간접 지분 = 출자비율 × 목적법인 지분", mst=_영MST,
    원문="2. 국가전략기술을 활용한 사업에서 발생한 매출액이 전체 매출액의 100분의 50 이상인 외국법인 3. 소재ㆍ부품ㆍ장비 품목의 매출액과 국가전략기술을 활용한 사업에서 발생한 매출액의 합계액이 전체 매출액의 100분의 50 이상인 외국법인",
    산출=("조특_13의3_인수대상",), 비고="사실 소부장매출비율, 전략기술매출비율, 부령품목생산, 목적법인출자비율, 목적법인지분비율, 직접지분비율.")
def 영12의3_7(ctx):
    a, b = _f(ctx.사실값("소부장매출비율")), _f(ctx.사실값("전략기술매출비율"))
    해당 = b >= 0.5 or a + b >= 0.5 or (ctx.사실값("부령품목생산", False) and (ctx.사실값("인수방식") != "주식" or a >= 0.5))
    지분 = _f(ctx.사실값("직접지분비율")) + _f(ctx.사실값("목적법인출자비율")) * _f(ctx.사실값("목적법인지분비율"))
    return {"조특_13의3_인수대상": {"해당": bool(해당), "지분비율": round(지분, 6)}}


@노드(id=_법ID + "-13의3-3", 법령=_법, 조="13의3", 항="3", 제목="2028년까지 소부장·국가전략기술 외국법인 인수(주식 기준지분 50%[최대주주 경영지배 30%] 이상 또는 사업·자산 양수) — 인수가액 5%(중견 7%, 중소 10%), 건별 5천억 초과분 제외", mst=_법MST,
    원문="③ … 주식등 취득가액 또는 사업ㆍ자산의 양수가액 … 의 100분의 5(중견기업의 경우에는 100분의 7, 중소기업의 경우에는 100분의 10)에 상당하는 금액을 해당 사업연도의 법인세에서 공제한다. 이 경우 … 인수건별 인수가액이 5천억원을 초과하는 경우 그 초과하는 금액은 없는 것으로 본다.",
    종료일="20281231", 준용=(_영ID + "-12의3-7",), 산출=("조특_13의3_인수공제액",),
    비고="감면유형 '외국법인인수'. 사실 인수일, 인수방식('주식'·'사업양수'), 인수가액(3년 내 양수 합산), 사업계속기간_년, 최대주주경영지배, 보유유지, 주주등비지배, 사업계속, 외국법인특수관계, 금융보험업, 공동인수_안분비율(⑥).")
def 법13의3_3(ctx):
    if not _유형(ctx, "외국법인인수"):
        return 미적용("감면유형에 외국법인인수 없음")
    일 = _d(ctx.사실값("인수일"))
    if 일 is None or 일 > date(2028, 12, 31):
        return 미적용("2028년 12월 31일 후 인수 — 일몰")
    if ctx.사실값("외국법인특수관계", False) or ctx.사실값("금융보험업", False):
        return 미적용("외국법인 특수관계 법인 또는 금융·보험업 법인 — 제외")
    r = ctx.값("조특_13의3_인수대상")
    if not r["해당"]:
        return 미적용("인수대상외국법인 아님(영 §12의3⑦)")
    if _f(ctx.사실값("사업계속기간_년")) < 1:
        return 미적용("각각 1년 이상 사업 계속 기업 아님")
    if ctx.사실값("인수방식", "주식") == "주식":
        기준 = 0.30 if ctx.사실값("최대주주경영지배", False) else 0.50
        if r["지분비율"] < 기준 or not ctx.사실값("보유유지", True):
            return 미적용("기준지분비율 %.0f%% 이상 취득·보유 요건 미충족(1호나목)" % (기준 * 100))
    if not ctx.사실값("주주등비지배", True) or not ctx.사실값("사업계속", True):
        return 미적용("주주등 지배주주 해당 또는 사업 미계속")
    율 = 0.10 if _중소(ctx) else (0.07 if ctx.값("조특_중견기업", False) else 0.05)
    가액 = min(_f(ctx.사실값("인수가액")), 500_000_000_000)
    return {"조특_13의3_인수공제액": _내림(가액 * 율 * _f(ctx.사실값("공동인수_안분비율"), 1.0))}


@노드(id=_법ID + "-13의3-4", 법령=_법, 조="13의3", 항="4", 제목="외국법인 인수 사후관리(인수 사업연도 다음 사업연도부터 4년) — 주주등 지배·사업 폐지 시 전액, 지분 감소 시 ⑤ 기준지분 이상이면 공제세액 × (당초 − 현재)/당초(기납부 제외), 이자상당액 가산(사업양수는 3호 미적용)", mst=_법MST,
    원문="⑤ 제4항제3호에 해당하는 경우로서 현재지분비율이 기준지분비율 이상인 경우에는 … (당초지분비율 － 현재지분비율) / 당초지분비율 × 제3항에 따른 공제세액 … (지분비율 감소로 이미 납부한 공제세액은 제외한다) …",
    준용=(_영ID + "-12의3-6",), 산출=("조특_13의3_인수추징",), 비고="사실 사후사유('주주지배'·'사업폐지'·'지분감소'), 사유일, 인수사업연도, 당초지분비율, 현재지분비율, 기납부공제세액, 공제받은세액.")
def 법13의3_4(ctx):
    사유 = ctx.사실값("사후사유")
    일 = _d(ctx.사실값("사유일"))
    if 사유 not in ("주주지배", "사업폐지", "지분감소") or 일 is None:
        return {"조특_13의3_인수추징": {"해당": False}}
    기간 = ctx.값("조특_13의3_사후기간")
    if not 기간[0] <= 일 <= 기간[1]:
        return {"조특_13의3_인수추징": {"해당": False, "사유": "사후관리 기간 밖"}}
    세 = _i(ctx.사실값("공제받은세액"))
    if 사유 == "지분감소":
        if ctx.사실값("인수방식", "주식") != "주식":
            return {"조특_13의3_인수추징": {"해당": False, "사유": "사업·자산 양수는 3호 미적용"}}
