@노드(id=_영ID + "-14-6", 법령=_영, 조="14", 항="6", 제목="소득공제 신청 — 출자·투자확인서 첨부, 근로·연말정산 사업자는 다음 연도 2월분 급여·사업소득 받는 날(퇴직·폐업 시 그 달), 그 밖은 종합소득 확정신고기한, ⑦ 시기변경신청서, ⑧⑨ 변경통지서·추징", mst=_영MST,
    원문="1. 「소득세법」 제73조의 규정이 적용되는 거주자는 당해 연도의 다음 연도 2월분의 급여 또는 사업소득을 받는 날 … 2. 제1호외의 거주자는 종합소득과세표준확정신고기한",
    산출=("조특_16_신청",))
def 영14_6(ctx):
    연말정산 = bool(ctx.사실값("연말정산대상", False))
